CREATE TABLE IF NOT EXISTS partner_meetings (id INT AUTO_INCREMENT PRIMARY KEY,company_id INT NOT NULL,title VARCHAR(220) NOT NULL,meeting_type VARCHAR(80) NOT NULL DEFAULT 'Partner meeting',scheduled_at DATETIME NOT NULL,location VARCHAR(255),agenda LONGTEXT,minutes LONGTEXT,resolution_text LONGTEXT,action_type VARCHAR(30) NOT NULL DEFAULT 'acknowledgement',response_due_date DATE,status VARCHAR(30) NOT NULL DEFAULT 'draft',created_by INT NULL,updated_by INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY ix_partner_meeting_company(company_id),KEY ix_partner_meeting_status(status),FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE CASCADE,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(updated_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS partner_meeting_responses (id INT AUTO_INCREMENT PRIMARY KEY,meeting_id INT NOT NULL,partner_id INT NOT NULL,response_status VARCHAR(30) NOT NULL DEFAULT 'pending',comment TEXT,responded_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_partner_meeting_response(meeting_id,partner_id),KEY ix_partner_response_partner(partner_id,response_status),FOREIGN KEY(meeting_id) REFERENCES partner_meetings(id) ON DELETE CASCADE,FOREIGN KEY(partner_id) REFERENCES partner_profiles(id) ON DELETE CASCADE);
